// Process comprehensive campaign management request
const campaignData = $input.first().json;
const { 
  action, // 'create', 'update', 'get', 'delete', 'recruit', 'schedule', 'archive', 'duplicate'
  campaignId,
  campaignInfo = {},
  playerData = [],
  sessionSchedule = {},
  worldBuildingData = {},
  progressMilestones = [],
  recruitmentData = {}
} = campaignData;

// Validate required fields
if (!action) {
  throw new Error('Missing required field: action');
}

if (action !== 'create' && !campaignId) {
  throw new Error('Missing required field: campaignId for action ' + action);
}

// Prepare operation data
const operationData = {
  action,
  campaignId: campaignId || `campaign_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
  timestamp: new Date().toISOString(),
  campaignInfo,
  playerData,
  sessionSchedule,
  worldBuildingData,
  progressMilestones,
  recruitmentData,
  metadata: {
    processedBy: 'comprehensive-campaign-management',
    version: '2.0',
    requestId: `req_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`
  }
};

return { json: operationData };

// Campaign creation with comprehensive world building
const campaignData = $input.first().json;
const { campaignId, campaignInfo, worldBuildingData } = campaignData;

// Campaign creation template with comprehensive world building
const newCampaign = {
  id: campaignId,
  name: campaignInfo.name || 'Untitled Campaign',
  description: campaignInfo.description || '',
  type: campaignInfo.type || 'fantasy', // fantasy, scifi, horror, modern, etc.
  difficulty: campaignInfo.difficulty || 'medium', // easy, medium, hard, legendary
  maxPlayers: campaignInfo.maxPlayers || 4,
  minPlayers: campaignInfo.minPlayers || 1,
  levelRange: campaignInfo.levelRange || { min: 1, max: 5 },
  setting: campaignInfo.setting || 'Custom World',
  theme: campaignInfo.theme || 'Adventure',
  estimatedDuration: campaignInfo.estimatedDuration || 'Medium (10-20 sessions)',

  // Campaign Status and Management
  status: 'recruiting', // recruiting, active, paused, completed, archived
  visibility: campaignInfo.visibility || 'public', // public, private, invite_only
  dmId: campaignInfo.dmId || null,

  // Player Management
  players: [],
  waitingList: [],
  playerApplications: [],
  partyComposition: {
    roles: [], // tank, healer, damage, support, utility, etc.
    balance: 0.0, // 0.0-1.0 score of party balance
    diversity: 0.0, // 0.0-1.0 score of class/race diversity
  },

  // Session Management
  sessionSchedule: {
    frequency: campaignInfo.sessionFrequency || 'weekly', // weekly, biweekly, monthly
    preferredDays: campaignInfo.preferredDays || ['Saturday'],
    preferredTime: campaignInfo.preferredTime || '19:00',
    timezone: campaignInfo.timezone || 'UTC',
    duration: campaignInfo.sessionDuration || 4, // hours
    nextSession: null,
    lastSession: null
  },

  // World Building Data
  worldBuilding: {
    worldName: worldBuildingData.worldName || campaignInfo.setting || 'Unknown World',
    worldType: worldBuildingData.worldType || campaignInfo.type || 'fantasy',
    geography: {
      continents: worldBuildingData.geography?.continents || [],
      regions: worldBuildingData.geography?.regions || [],
      cities: worldBuildingData.geography?.cities || [],
      dungeons: worldBuildingData.geography?.dungeons || [],
      pointsOfInterest: worldBuildingData.geography?.pointsOfInterest || []
    },
    politics: {
      kingdoms: worldBuildingData.politics?.kingdoms || [],
      factions: worldBuildingData.politics?.factions || [],
      governments: worldBuildingData.politics?.governments || [],
      relationships: worldBuildingData.politics?.relationships || {}
    },
    history: {
      ancientEvents: worldBuildingData.history?.ancientEvents || [],
      recentHistory: worldBuildingData.history?.recentHistory || [],
      prophecies: worldBuildingData.history?.prophecies || [],
      timelines: worldBuildingData.history?.timelines || []
    },
    culture: {
      races: worldBuildingData.culture?.races || [],
      religions: worldBuildingData.culture?.religions || [],
      traditions: worldBuildingData.culture?.traditions || [],
      languages: worldBuildingData.culture?.languages || []
    },
    economy: {
      currencies: worldBuildingData.economy?.currencies || [],
      tradeRoutes: worldBuildingData.economy?.tradeRoutes || [],
      resources: worldBuildingData.economy?.resources || [],
      markets: worldBuildingData.economy?.markets || []
    },
    magic: {
      systems: worldBuildingData.magic?.systems || [],
      restrictions: worldBuildingData.magic?.restrictions || [],
      artifacts: worldBuildingData.magic?.artifacts || [],
      sources: worldBuildingData.magic?.sources || []
    }
  },

  // Progress Tracking
  progressMilestones: campaignData.progressMilestones || [
    {
      id: 'milestone_start',
      name: 'Campaign Beginning',
      description: 'The start of the adventure',
      completed: false,
      completedDate: null,
      rewards: { experience: 0, gold: 0, items: [] }
    }
  ],
  currentMilestone: 0,
  overallProgress: 0.0, // 0.0-1.0

  // Story and Narrative
  mainQuestline: {
    name: campaignInfo.mainQuestName || 'The Main Adventure',
    description: campaignInfo.mainQuestDescription || 'An epic journey awaits',
    objectives: [],
    currentObjective: 0,
    completedObjectives: []
  },
  sideQuests: [],
  completedQuests: [],

  // Campaign Statistics
  statistics: {
    totalSessions: 0,
    totalPlaytime: 0, // in hours
    averageSessionLength: 0,
    playerRetentionRate: 1.0,
    questCompletionRate: 0.0,
    combatEncounters: 0,
    roleplaySessions: 0,
    explorationSessions: 0,
    puzzlesSolved: 0,
    itemsDiscovered: 0,
    enemiesDefeated: 0
  },

  // Metadata
  createdAt: new Date().toISOString(),
  createdBy: campaignInfo.createdBy || 'system',
  lastUpdated: new Date().toISOString(),
  tags: campaignInfo.tags || [],
  notes: campaignInfo.notes || '',

  // Configuration
  settings: {
    allowPlayerCreation: campaignInfo.allowPlayerCreation !== false,
    requireCharacterApproval: campaignInfo.requireCharacterApproval !== false,
    enableDeathSavingThrows: campaignInfo.enableDeathSavingThrows !== false,
    levelingSystem: campaignInfo.levelingSystem || 'standard',
    restingRules: campaignInfo.restingRules || 'standard',
    inventoryManagement: campaignInfo.inventoryManagement || 'manual'
  }
};

return { json: newCampaign };

// Player recruitment and party management system
const campaignData = $input.first().json;
const { campaignId, playerData, recruitmentData } = campaignData;

// Get current campaign state
let currentCampaign = null;
if ($input.length > 1 && $input[1].json && $input[1].json.values) {
  const dataRow = $input[1].json.values.find(row => row[0] === campaignId);
  if (dataRow) {
    currentCampaign = {
      id: dataRow[0],
      name: dataRow[1],
      status: dataRow[2],
      players: JSON.parse(dataRow[3] || '[]'),
      waitingList: JSON.parse(dataRow[4] || '[]'),
      playerApplications: JSON.parse(dataRow[5] || '[]'),
      partyComposition: JSON.parse(dataRow[6] || '{}'),
      maxPlayers: parseInt(dataRow[7]) || 4,
      minPlayers: parseInt(dataRow[8]) || 1,
      settings: JSON.parse(dataRow[9] || '{}'),
      lastUpdated: dataRow[10] || new Date().toISOString()
    };
  }
}

if (!currentCampaign) {
  throw new Error('Campaign not found: ' + campaignId);
}

// Process player recruitment
let updatedPlayers = [...currentCampaign.players];
let updatedWaitingList = [...currentCampaign.waitingList];
let updatedApplications = [...currentCampaign.playerApplications];

playerData.forEach(player => {
  const { playerId, action: playerAction, data } = player;

  if (playerAction === 'apply') {
    // New player application
    const application = {
      id: `app_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
      playerId,
      playerName: data.playerName,
      playerEmail: data.playerEmail,
      experience: data.experience || 'beginner',
      preferredRole: data.preferredRole || 'damage',
      characterConcept: data.characterConcept || '',
      availability: data.availability || {},
      message: data.message || '',
      appliedAt: new Date().toISOString(),
      status: 'pending' // pending, approved, rejected, waitlisted
    };

    updatedApplications.push(application);

  } else if (playerAction === 'approve') {
    // Approve player application
    const appIndex = updatedApplications.findIndex(app => 
      app.id === data.applicationId || app.playerId === playerId
    );

    if (appIndex >= 0) {
      const application = updatedApplications[appIndex];

      if (updatedPlayers.length < currentCampaign.maxPlayers) {
        // Add to active players
        const playerInfo = {
          id: application.playerId,
          name: application.playerName,
          email: application.playerEmail,
          experience: application.experience,
          role: application.preferredRole,
          character: data.character || null,
          joinedAt: new Date().toISOString(),
          status: 'active', // active, inactive, away
          attendance: {
            sessionsAttended: 0,
            sessionsMissed: 0,
            lastAttendance: null
          },
          contributions: {
            roleplayMoments: 0,
            combatHighlights: 0,
            puzzleSolutions: 0,
            creativeSolutions: 0
          }
        };

        updatedPlayers.push(playerInfo);
        application.status = 'approved';
        updatedApplications[appIndex] = application;

      } else {
        // Add to waiting list
        application.status = 'waitlisted';
        updatedApplications[appIndex] = application;

        updatedWaitingList.push({
          id: application.playerId,
          name: application.playerName,
          email: application.playerEmail,
          role: application.preferredRole,
          waitlistedAt: new Date().toISOString(),
          priority: updatedWaitingList.length + 1
        });
      }
    }

  } else if (playerAction === 'remove') {
    // Remove player from campaign
    const playerIndex = updatedPlayers.findIndex(p => p.id === playerId);
    if (playerIndex >= 0) {
      const removedPlayer = updatedPlayers[playerIndex];
      removedPlayer.status = 'removed';
      removedPlayer.removedAt = new Date().toISOString();
      removedPlayer.reason = data.reason || 'Left campaign';

      // Move from active to historical or remove completely
      updatedPlayers.splice(playerIndex, 1);

      // If there's someone on the waiting list, offer them the spot
      if (updatedWaitingList.length > 0) {
        const nextPlayer = updatedWaitingList.shift();
        updatedApplications = updatedApplications.map(app => {
          if (app.playerId === nextPlayer.id) {
            return { ...app, status: 'offered', offeredAt: new Date().toISOString() };
          }
          return app;
        });
      }
    }

  } else if (playerAction === 'update') {
    // Update player information
    const playerIndex = updatedPlayers.findIndex(p => p.id === playerId);
    if (playerIndex >= 0) {
      updatedPlayers[playerIndex] = {
        ...updatedPlayers[playerIndex],
        ...data,
        lastUpdated: new Date().toISOString()
      };
    }
  }
});

// Calculate party composition balance
const roleDistribution = updatedPlayers.reduce((acc, player) => {
  acc[player.role] = (acc[player.role] || 0) + 1;
  return acc;
}, {});

const idealDistribution = {
  tank: updatedPlayers.length > 2 ? 1 : 0.3,
  healer: updatedPlayers.length > 2 ? 1 : 0.3,
  damage: updatedPlayers.length * 0.4,
  support: updatedPlayers.length * 0.2,
  utility: updatedPlayers.length * 0.1
};

// Calculate balance score (0.0-1.0)
let balanceScore = 0.0;
let totalRoles = 0;

Object.keys(idealDistribution).forEach(role => {
  const actual = roleDistribution[role] || 0;
  const ideal = idealDistribution[role];
  const diff = Math.abs(actual - ideal);
  const roleScore = Math.max(0, 1 - (diff / Math.max(actual, ideal, 1)));
  balanceScore += roleScore;
  totalRoles++;
});

if (totalRoles > 0) {
  balanceScore = balanceScore / totalRoles;
}

// Update campaign status based on player count
let newStatus = currentCampaign.status;
if (updatedPlayers.length >= currentCampaign.minPlayers && currentCampaign.status === 'recruiting') {
  newStatus = 'ready';
} else if (updatedPlayers.length < currentCampaign.minPlayers && currentCampaign.status === 'ready') {
  newStatus = 'recruiting';
}

const updatedCampaign = {
  ...currentCampaign,
  players: updatedPlayers,
  waitingList: updatedWaitingList,
  playerApplications: updatedApplications,
  partyComposition: {
    roles: roleDistribution,
    balance: Math.round(balanceScore * 100) / 100,
    diversity: calculateDiversityScore(updatedPlayers)
  },
  status: newStatus,
  lastUpdated: new Date().toISOString(),
  metadata: {
    playersAdded: updatedPlayers.length - currentCampaign.players.length,
    playersRemoved: currentCampaign.players.length - updatedPlayers.length,
    applicationsProcessed: playerData.length
  }
};

return { json: updatedCampaign };

// Helper function to calculate party diversity
function calculateDiversityScore(players) {
  if (players.length <= 1) return 1.0;

  const races = new Set();
  const classes = new Set();
  const roles = new Set();

  players.forEach(player => {
    if (player.character) {
      if (player.character.race) races.add(player.character.race);
      if (player.character.class) classes.add(player.character.class);
    }
    roles.add(player.role);
  });

  const diversityFactors = [
    races.size / players.length,
    classes.size / players.length,
    roles.size / players.length
  ];

  return diversityFactors.reduce((sum, factor) => sum + factor, 0) / diversityFactors.length;
}

// Session scheduling and organization system
const campaignData = $input.first().json;
const { campaignId, sessionSchedule } = campaignData;

// Get current campaign state
let currentCampaign = null;
if ($input.length > 1 && $input[1].json && $input[1].json.values) {
  const dataRow = $input[1].json.values.find(row => row[0] === campaignId);
  if (dataRow) {
    currentCampaign = {
      id: dataRow[0],
      name: dataRow[1],
      sessionSchedule: JSON.parse(dataRow[2] || '{}'),
      players: JSON.parse(dataRow[3] || '[]'),
      lastUpdated: dataRow[4] || new Date().toISOString()
    };
  }
}

if (!currentCampaign) {
  throw new Error('Campaign not found: ' + campaignId);
}

// Process session scheduling
let updatedSchedule = { ...currentCampaign.sessionSchedule };
let sessionEvents = [];

if (sessionSchedule.action === 'schedule') {
  const { sessionData } = sessionSchedule;

  // Create new session
  const newSession = {
    id: `session_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
    campaignId,
    scheduledFor: sessionData.scheduledFor,
    duration: sessionData.duration || updatedSchedule.duration || 4,
    timezone: sessionData.timezone || updatedSchedule.timezone || 'UTC',
    location: sessionData.location || 'Online',
    type: sessionData.type || 'regular', // regular, special, one_shot, finale
    status: 'scheduled', // scheduled, in_progress, completed, cancelled

    // Session content planning
    plannedContent: {
      mainPlot: sessionData.mainPlot || '',
      subplots: sessionData.subplots || [],
      encounters: sessionData.encounters || [],
      locations: sessionData.locations || [],
      npcs: sessionData.npcs || [],
      rewards: sessionData.rewards || {}
    },

    // Player availability
    playerAvailability: {},
    attendanceConfirmed: [],
    attendanceDeclined: [],
    attendancePending: currentCampaign.players.map(p => p.id),

    // Session tracking
    createdAt: new Date().toISOString(),
    createdBy: sessionSchedule.createdBy || 'dm',
    lastUpdated: new Date().toISOString()
  };

  // Initialize player availability
  currentCampaign.players.forEach(player => {
    newSession.playerAvailability[player.id] = {
      available: null, // null = unknown, true = available, false = unavailable
      respondedAt: null,
      notes: ''
    };
  });

  // Add to session schedule
  if (!updatedSchedule.upcomingSessions) {
    updatedSchedule.upcomingSessions = [];
  }
  updatedSchedule.upcomingSessions.push(newSession);
  updatedSchedule.nextSession = newSession;

  sessionEvents.push({
    type: 'session_scheduled',
    sessionId: newSession.id,
    scheduledFor: newSession.scheduledFor,
    playersNotified: currentCampaign.players.map(p => p.id)
  });

} else if (sessionSchedule.action === 'reschedule') {
  const { sessionId, newTime, reason } = sessionSchedule;

  if (updatedSchedule.upcomingSessions) {
    const sessionIndex = updatedSchedule.upcomingSessions.findIndex(s => s.id === sessionId);
    if (sessionIndex >= 0) {
      const session = updatedSchedule.upcomingSessions[sessionIndex];
      session.previousTime = session.scheduledFor;
      session.scheduledFor = newTime;
      session.rescheduleReason = reason;
      session.lastUpdated = new Date().toISOString();

      // Reset attendance responses
      session.attendanceConfirmed = [];
      session.attendanceDeclined = [];
      session.attendancePending = currentCampaign.players.map(p => p.id);

      Object.keys(session.playerAvailability).forEach(playerId => {
        session.playerAvailability[playerId] = {
          available: null,
          respondedAt: null,
          notes: ''
        };
      });

      sessionEvents.push({
        type: 'session_rescheduled',
        sessionId,
        previousTime: session.previousTime,
        newTime,
        reason
      });
    }
  }

} else if (sessionSchedule.action === 'cancel') {
  const { sessionId, reason } = sessionSchedule;

  if (updatedSchedule.upcomingSessions) {
    const sessionIndex = updatedSchedule.upcomingSessions.findIndex(s => s.id === sessionId);
    if (sessionIndex >= 0) {
      const session = updatedSchedule.upcomingSessions[sessionIndex];
      session.status = 'cancelled';
      session.cancelledAt = new Date().toISOString();
      session.cancelReason = reason;

      // Update next session if needed
      if (updatedSchedule.nextSession && updatedSchedule.nextSession.id === sessionId) {
        updatedSchedule.nextSession = updatedSchedule.upcomingSessions
          .filter(s => s.status === 'scheduled')
          .sort((a, b) => new Date(a.scheduledFor) - new Date(b.scheduledFor))[0] || null;
      }

      sessionEvents.push({
        type: 'session_cancelled',
        sessionId,
        reason
      });
    }
  }

} else if (sessionSchedule.action === 'confirm_attendance') {
  const { sessionId, playerId, available, notes } = sessionSchedule;

  if (updatedSchedule.upcomingSessions) {
    const session = updatedSchedule.upcomingSessions.find(s => s.id === sessionId);
    if (session && session.playerAvailability[playerId]) {
      session.playerAvailability[playerId] = {
        available,
        respondedAt: new Date().toISOString(),
        notes: notes || ''
      };

      // Update attendance lists
      session.attendancePending = session.attendancePending.filter(id => id !== playerId);

      if (available) {
        session.attendanceConfirmed.push(playerId);
      } else {
        session.attendanceDeclined.push(playerId);
      }

      session.lastUpdated = new Date().toISOString();

      sessionEvents.push({
        type: 'attendance_confirmed',
        sessionId,
        playerId,
        available
      });
    }
  }
}

// Update campaign schedule settings
if (sessionSchedule.settings) {
  updatedSchedule = {
    ...updatedSchedule,
    ...sessionSchedule.settings,
    lastUpdated: new Date().toISOString()
  };
}

const updatedCampaign = {
  ...currentCampaign,
  sessionSchedule: updatedSchedule,
  lastUpdated: new Date().toISOString(),
  metadata: {
    scheduleEvents: sessionEvents,
    upcomingSessionCount: updatedSchedule.upcomingSessions?.filter(s => s.status === 'scheduled').length || 0
  }
};

return { json: updatedCampaign };

// Campaign progress tracking and milestone management
const campaignData = $input.first().json;
const { campaignId, progressMilestones } = campaignData;

// Get current campaign state
let currentCampaign = null;
if ($input.length > 1 && $input[1].json && $input[1].json.values) {
  const dataRow = $input[1].json.values.find(row => row[0] === campaignId);
  if (dataRow) {
    currentCampaign = {
      id: dataRow[0],
      name: dataRow[1],
      progressMilestones: JSON.parse(dataRow[2] || '[]'),
      currentMilestone: parseInt(dataRow[3]) || 0,
      overallProgress: parseFloat(dataRow[4]) || 0.0,
      mainQuestline: JSON.parse(dataRow[5] || '{}'),
      completedQuests: JSON.parse(dataRow[6] || '[]'),
      statistics: JSON.parse(dataRow[7] || '{}'),
      lastUpdated: dataRow[8] || new Date().toISOString()
    };
  }
}

if (!currentCampaign) {
  throw new Error('Campaign not found: ' + campaignId);
}

// Process milestone updates
let updatedMilestones = [...currentCampaign.progressMilestones];
let updatedCurrentMilestone = currentCampaign.currentMilestone;
let milestoneCompletions = [];

progressMilestones.forEach(milestoneUpdate => {
  const { milestoneId, action: milestoneAction, data } = milestoneUpdate;

  if (milestoneAction === 'complete') {
    const milestoneIndex = updatedMilestones.findIndex(m => m.id === milestoneId);
    if (milestoneIndex >= 0) {
      const milestone = updatedMilestones[milestoneIndex];
      if (!milestone.completed) {
        milestone.completed = true;
        milestone.completedDate = new Date().toISOString();
        milestone.completedBy = data.completedBy || 'party';
        milestone.completionNotes = data.notes || '';

        // Award milestone rewards
        if (data.awardRewards !== false && milestone.rewards) {
          // This would integrate with character system to award XP, gold, items
          milestoneCompletions.push({
            type: 'milestone_completed',
            milestoneId,
            milestoneName: milestone.name,
            rewards: milestone.rewards
          });
        }

        updatedMilestones[milestoneIndex] = milestone;

        // Check if this was the current milestone and advance
        if (milestoneIndex === updatedCurrentMilestone) {
          updatedCurrentMilestone = milestoneIndex + 1;
        }
      }
    }

  } else if (milestoneAction === 'add') {
    const newMilestone = {
      id: milestoneId,
      name: data.name || 'New Milestone',
      description: data.description || '',
      prerequisites: data.prerequisites || [],
      objectives: data.objectives || [],
      rewards: data.rewards || { experience: 0, gold: 0, items: [] },
      completed: false,
      completedDate: null,
      completedBy: null,
      completionNotes: '',
      createdAt: new Date().toISOString(),
      category: data.category || 'story', // story, combat, exploration, social
      difficulty: data.difficulty || 'normal',
      estimatedTime: data.estimatedTime || '1 session'
    };

    updatedMilestones.push(newMilestone);

  } else if (milestoneAction === 'update') {
    const milestoneIndex = updatedMilestones.findIndex(m => m.id === milestoneId);
    if (milestoneIndex >= 0) {
      updatedMilestones[milestoneIndex] = {
        ...updatedMilestones[milestoneIndex],
        ...data,
        lastModified: new Date().toISOString()
      };
    }
  }
});

// Calculate overall campaign progress
const completedMilestones = updatedMilestones.filter(m => m.completed).length;
const totalMilestones = updatedMilestones.length;
const overallProgress = totalMilestones > 0 ? Math.round((completedMilestones / totalMilestones) * 100) / 100 : 0.0;

// Update campaign statistics
const updatedStatistics = {
  ...currentCampaign.statistics,
  milestonesCompleted: completedMilestones,
  totalMilestones,
  campaignProgress: overallProgress,
  lastMilestoneCompleted: milestoneCompletions.length > 0 ? 
    milestoneCompletions[milestoneCompletions.length - 1].milestoneName : null
};

// Check for campaign completion
let campaignStatus = currentCampaign.status;
if (overallProgress >= 1.0 && campaignStatus !== 'completed') {
  campaignStatus = 'completed';
  milestoneCompletions.push({
    type: 'campaign_completed',
    completedAt: new Date().toISOString(),
    totalMilestones,
    finalProgress: overallProgress
  });
}

const updatedCampaign = {
  ...currentCampaign,
  progressMilestones: updatedMilestones,
  currentMilestone: updatedCurrentMilestone,
  overallProgress,
  statistics: updatedStatistics,
  status: campaignStatus,
  lastUpdated: new Date().toISOString(),
  metadata: {
    milestoneCompletions,
    progressChange: overallProgress - currentCampaign.overallProgress
  }
};

return { json: updatedCampaign };

// Send campaign updates to connected systems
const campaignData = $input.first().json;
const { campaignId, metadata } = campaignData;

// Prepare WebSocket broadcast payload
const broadcastPayload = {
  type: 'campaign_update',
  data: {
    campaignId,
    name: campaignData.name,
    status: campaignData.status,
    playerCount: campaignData.players.length,
    maxPlayers: campaignData.maxPlayers,
    overallProgress: campaignData.overallProgress,
    nextSession: campaignData.sessionSchedule?.nextSession?.scheduledFor || null,
    partyBalance: campaignData.partyComposition?.balance || 0.0
  },
  channels: [`campaign_${campaignId}`, 'campaign_updates', 'dm_updates'],
  timestamp: new Date().toISOString()
};

// Send to WebSocket system
fetch('http://localhost:5678/webhook/websocket/broadcast', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(broadcastPayload)
}).catch(error => {
  console.error('Failed to broadcast campaign update:', error);
});

// Send notifications for specific events
if (metadata?.milestoneCompletions?.length > 0) {
  metadata.milestoneCompletions.forEach(completion => {
    const notificationPayload = {
      type: 'milestone_completion',
      data: {
        campaignId,
        campaignName: campaignData.name,
        ...completion
      },
      channels: [`campaign_${campaignId}`, 'milestone_updates'],
      timestamp: new Date().toISOString()
    };

    fetch('http://localhost:5678/webhook/websocket/broadcast', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(notificationPayload)
    }).catch(error => {
      console.error('Failed to broadcast milestone completion:', error);
    });
  });
}

if (metadata?.scheduleEvents?.length > 0) {
  metadata.scheduleEvents.forEach(event => {
    const notificationPayload = {
      type: 'schedule_update',
      data: {
        campaignId,
        campaignName: campaignData.name,
        ...event
      },
      channels: [`campaign_${campaignId}`, 'schedule_updates'],
      timestamp: new Date().toISOString()
    };

    fetch('http://localhost:5678/webhook/websocket/broadcast', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(notificationPayload)
    }).catch(error => {
      console.error('Failed to broadcast schedule update:', error);
    });
  });
}

return { json: { broadcast: 'sent', campaignId, events: metadata } };

